    internal enum BastionBalanceKind { Float,Int,Bool }
    internal sealed class BastionBalanceSpec
    {
        internal readonly BastionSetting Key;internal readonly string Category,Name,Description;
        // Keep these unused profile slots to preserve existing wire ordinals.
        internal bool Retired=>Key==BastionSetting.MineLeapRange||Key==BastionSetting.MineLeapTime||Key==BastionSetting.MineFuse;
        internal readonly float Default,Minimum,Maximum,Step;internal readonly BastionBalanceKind Kind;
        internal BastionBalanceSpec(BastionSetting key,string category,string name,float value,float minimum,float maximum,float step,BastionBalanceKind kind,string description)
        {Key=key;Category=category;Name=name;Default=value;Minimum=minimum;Maximum=maximum;Step=step;Kind=kind;Description=description;}
        internal float Sanitize(float value)
        {
            if(float.IsNaN(value)||float.IsInfinity(value))return Default;
            value=Math.Max(Minimum,Math.Min(Maximum,value));
            return Kind==BastionBalanceKind.Float?value:(float)Math.Round(value,MidpointRounding.AwayFromZero);
        }
    }
