        private static float[] active=Defaults();
        internal static float[] Defaults(){var values=new float[Specs.Length];for(int i=0;i<values.Length;i++)values[i]=Specs[i].Default;return values;}
        internal static float Get(BastionSetting key)=>active[(int)key];
        internal static float Fraction(BastionSetting key)=>Get(key)/100f;
        internal static int Int(BastionSetting key)=>(int)Get(key);
        internal static bool Enabled(BastionSetting key)=>Get(key)>.5f;
        internal static float[] Snapshot()=>(float[])active.Clone();
        internal static bool Apply(float[] values)
        {
            if(values==null||values.Length!=Specs.Length)return false;
            var next=new float[values.Length];for(int i=0;i<next.Length;i++)next[i]=Specs[i].Sanitize(values[i]);active=next;return true;
        }
        internal static void Reset()=>active=Defaults();
    }
